-- # Lernfeld 5: Cyberphysische Systeme > ## Testgetriebene Entwicklung > - Dokumentation > - Unterlagen

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind Unterlagen in der testgetriebenen Entwicklung (TDD) notwendig, um den Entwicklungsprozess nachzuvollziehen?', 2, '[{"text": "Ja", "correct": true, "because": "Unterlagen ergänzen Tests"}, {"text": "Nein", "correct": false, "because": "Nachvollziehbarkeit wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Tests in TDD vollständig die traditionelle Dokumentation wie Spezifikationen ersetzen?', 2, '[{"text": "Nein", "correct": true, "because": "Tests ergänzen, ersetzen nicht"}, {"text": "Ja", "correct": false, "because": "Zusätzliche Infos nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Erstellung von Unterlagen in TDD immer zeitaufwendiger als das Schreiben von Tests?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt vom Umfang ab"}, {"text": "Ja", "correct": false, "because": "Variabel je nach Projekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Fehlen von Unterlagen in TDD die Wartbarkeit der Software beeinträchtigen?', 2, '[{"text": "Ja", "correct": true, "because": "Unterlagen erleichtern Verständnis"}, {"text": "Nein", "correct": false, "because": "Tests allein oft unzureichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Unterlagen in TDD nur für große Projekte sinnvoll?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Breite Anwendbarkeit"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Unterlagen in TDD?', 2, '[{"text": "Ergänzung der Tests als Dokumentation", "correct": true, "because": "Tests und Unterlagen zusammen"}, {"text": "Ersetzung der Tests", "correct": false, "because": "Tests zentral"}, {"text": "Optimierung der Laufzeit", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Unterlagen ist in TDD besonders nützlich?', 3, '[{"text": "Anforderungsdokumentation", "correct": true, "because": "Basis für Tests"}, {"text": "Code-Kommentare", "correct": false, "because": "Ergänzend"}, {"text": "Benutzerhandbuch", "correct": false, "because": "Später relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich aus gut gepflegten Unterlagen in TDD?', 2, '[{"text": "Verbesserte Nachvollziehbarkeit", "correct": true, "because": "Erleichtert Verständnis"}, {"text": "Schnellere Testausführung", "correct": false, "because": "Nicht primär"}, {"text": "Weniger Testaufwand", "correct": false, "because": "Tests bleiben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt der Unterlagen unterstützt die Wartbarkeit in TDD?', 2, '[{"text": "Klarheit über Anforderungen", "correct": true, "because": "Erleichtert Änderungen"}, {"text": "Hohe Komplexität", "correct": false, "because": "Hinderlich"}, {"text": "Manuelle Validierung", "correct": false, "because": "Tests übernehmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip von TDD wird durch Unterlagen ergänzt?', 2, '[{"text": "Testgetriebene Spezifikation", "correct": true, "because": "Unterlagen spezifizieren Tests"}, {"text": "Maximale Abdeckung", "correct": false, "because": "Ziel, nicht Prinzip"}, {"text": "Code-Optimierung", "correct": false, "because": "Refactoring"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Unterlagen sind in TDD sinnvoll?', 4, '[{"text": "Anforderungsdokumente", "correct": true, "because": "Basis für Tests"}, {"text": "Testberichte", "correct": true, "because": "Zeigen Ergebnisse"}, {"text": "Marketingpläne", "correct": false, "because": "Nicht TDD-relevant"}, {"text": "Architekturübersichten", "correct": true, "because": "Strukturverständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Unterlagen in TDD?', 3, '[{"text": "Nachvollziehbarkeit", "correct": true, "because": "Verständnis erleichtert"}, {"text": "Teamkommunikation", "correct": true, "because": "Klarheit für alle"}, {"text": "Schnellere Tests", "correct": false, "because": "Nicht primär"}, {"text": "Wartungsunterstützung", "correct": true, "because": "Änderungen einfacher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei der Erstellung von Unterlagen in TDD?', 3, '[{"text": "Zeitaufwand", "correct": true, "because": "Erstellung kostet Zeit"}, {"text": "Synchronisation mit Tests", "correct": true, "because": "Änderungen müssen passen"}, {"text": "Keine Testunterstützung", "correct": false, "because": "Tests zentral"}, {"text": "Komplexität bei Wartung", "correct": true, "because": "Aktualisierung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte der Unterlagen unterstützen TDD?', 4, '[{"text": "Klarheit über Anforderungen", "correct": true, "because": "Tests basieren darauf"}, {"text": "Projektübersicht", "correct": true, "because": "Kontextverständnis"}, {"text": "Manuelle Testanweisungen", "correct": false, "because": "Automatisierung zentral"}, {"text": "Wartungshilfe", "correct": true, "because": "Änderungen erleichtert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sollten in TDD-Unterlagen enthalten sein?', 3, '[{"text": "Testbeschreibungen", "correct": true, "because": "Ergänzen Tests"}, {"text": "Anforderungen", "correct": true, "because": "Grundlage für Entwicklung"}, {"text": "Hardwareanforderungen", "correct": false, "because": "Weniger relevant"}, {"text": "Änderungsprotokolle", "correct": true, "because": "Nachvollziehbarkeit"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Unterlagen in TDD sind nur für große Teams nötig. b) Unterlagen ergänzen Tests als Dokumentation.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Auch kleine Teams profitieren, Ergänzung real"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Unterlagen in TDD verbessern die Wartbarkeit. b) Tests machen Unterlagen überflüssig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wartbarkeit steigt, Unterlagen ergänzen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Unterlagen in TDD sind immer zeitaufwendiger als Tests. b) Anforderungsdokumente sind in TDD nützlich.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Zeit variabel, Anforderungen hilfreich"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Unterlagen in TDD unterstützen die Teamkommunikation. b) TDD erfordert keine Unterlagen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kommunikation verbessert, Unterlagen hilfreich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Unterlagen in TDD sind optional, aber nützlich. b) Unterlagen ersetzen Tests in TDD.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Optional ja, Tests zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

